WHERE {
  ?singer :singer\#age ?age .
  ?singer :singer\#song_name ?song_name .
  FILTER (?age > (
    SELECT (AVG(?avg_age) AS ?average_age)
    WHERE {
      ?singer2 :singer\#age ?avg_age .
    }
  ))
}

