execution_result.cleaned_query:
SELECT ?song_name
WHERE {
  ?singer :singer\#age ?age .
  ?singer :singer\#song_name ?song_name .
  {
    SELECT (AVG(?avg_age) AS ?average_age)
    WHERE {
      ?singer :singer\#age ?avg_age .
    }
  } AS ?avg_query
  FILTER (?age > ?avg_query)
}

