Natural Language Question: What are the names , themes , and number of singers for every concert ?

execution_result.cleaned_query:
SELECT ?concertName ?theme (COUNT(?singer) AS ?numSingers)
WHERE {
  ?concert :concert\#concert_name ?concertName ;
           :concert\#theme ?theme ;
           :concert\#concert_id ?concertId .
  ?singerInConcert :singer_in_concert\#ref-concert_id ?concert ;
                   :singer_in_concert\#ref-singer_id ?singer .
}
GROUP BY ?concertName ?theme

